-- A5 WEBSITE: EXACT COMBINED SUPABASE MIGRATIONS
-- Generated by concatenating the repository migrations in numeric order.
-- Run once on a NEW, EMPTY Supabase project. Do not rerun on a populated database.
-- Each migration retains its own BEGIN/COMMIT transaction boundary.


-- ==================== 0001_core_schema.sql ====================
-- A5 website: Supabase primary database schema
-- Apply with Supabase CLI or SQL Editor. No secrets belong in this file.

begin;

create extension if not exists pgcrypto with schema extensions;

-- Keep application settings in UTC; clients may render in the administrator's timezone.
set timezone = 'UTC';

create table if not exists public.visitors (
  id uuid primary key default gen_random_uuid(),
  visitor_key text not null unique check (length(visitor_key) between 12 and 160),
  first_seen_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  first_source text,
  last_source text,
  first_landing_path text,
  last_landing_path text,
  is_admin boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.visitor_sessions (
  id uuid primary key default gen_random_uuid(),
  session_key text not null unique check (length(session_key) between 12 and 160),
  visitor_id uuid not null references public.visitors(id) on delete cascade,
  started_at timestamptz not null default now(),
  last_activity_at timestamptz not null default now(),
  ended_at timestamptz,
  landing_path text not null default '/',
  exit_path text,
  referrer_host text,
  utm_source text,
  utm_medium text,
  utm_campaign text,
  utm_content text,
  utm_term text,
  source text,
  device_type text,
  browser text,
  operating_system text,
  country text,
  city text,
  is_admin boolean not null default false,
  created_at timestamptz not null default now(),
  constraint visitor_sessions_time_check check (ended_at is null or ended_at >= started_at)
);

create table if not exists public.tracking_events (
  id uuid primary key default gen_random_uuid(),
  event_id text not null unique check (length(event_id) between 8 and 180),
  visitor_id uuid references public.visitors(id) on delete set null,
  session_id uuid references public.visitor_sessions(id) on delete set null,
  event_type text not null check (event_type in (
    'page_view', 'session_start', 'session_end', 'cta_click',
    'whatsapp_click', 'contact_submit', 'download',
    'visit', 'visit_exit', 'custom'
  )),
  page_path text not null default '/',
  occurred_at timestamptz not null default now(),
  source text,
  campaign text,
  properties jsonb not null default '{}'::jsonb,
  is_admin boolean not null default false,
  created_at timestamptz not null default now(),
  constraint tracking_events_properties_object check (jsonb_typeof(properties) = 'object')
);

create table if not exists public.contact_submissions (
  id uuid primary key default gen_random_uuid(),
  submission_ref text not null unique,
  created_at timestamptz not null default now(),
  status text not null default 'new' check (status in ('new', 'in_progress', 'replied', 'closed', 'spam')),
  source_page text,
  visitor_id uuid references public.visitors(id) on delete set null,
  session_id uuid references public.visitor_sessions(id) on delete set null,
  name text,
  email text,
  phone text,
  message text,
  metadata jsonb not null default '{}'::jsonb,
  constraint contact_submissions_metadata_object check (jsonb_typeof(metadata) = 'object')
);

create table if not exists public.email_open_events (
  id uuid primary key default gen_random_uuid(),
  recipient_hash text,
  campaign text,
  message_id text,
  subject text,
  country text,
  city text,
  user_agent text,
  requested_at timestamptz not null default now(),
  request_id text,
  metadata jsonb not null default '{}'::jsonb,
  constraint email_open_metadata_object check (jsonb_typeof(metadata) = 'object')
);

create table if not exists public.site_settings (
  key text primary key check (length(key) between 1 and 100),
  value jsonb not null default '{}'::jsonb,
  description text,
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null,
  constraint site_settings_value_object check (jsonb_typeof(value) in ('object', 'array', 'string', 'number', 'boolean', 'null'))
);

create table if not exists public.integration_settings (
  provider text primary key check (provider in ('google_sheets', 'telegram')),
  enabled boolean not null default false,
  options jsonb not null default '{}'::jsonb,
  last_tested_at timestamptz,
  last_test_status text check (last_test_status in ('success', 'failed', 'unknown')),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users(id) on delete set null,
  constraint integration_options_object check (jsonb_typeof(options) = 'object')
);

create table if not exists public.admin_profiles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  display_name text,
  role text not null default 'admin' check (role in ('owner', 'admin')),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.admin_activity_logs (
  id bigint generated always as identity primary key,
  actor_user_id uuid references auth.users(id) on delete set null,
  action text not null check (length(action) between 1 and 120),
  target_type text,
  target_id text,
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint admin_activity_metadata_object check (jsonb_typeof(metadata) = 'object')
);

create table if not exists public.export_jobs (
  id bigint generated always as identity primary key,
  event_id text not null references public.tracking_events(event_id) on delete cascade,
  provider text not null check (provider = 'google_sheets'),
  status text not null default 'pending' check (status in ('pending', 'processing', 'succeeded', 'failed', 'cancelled')),
  attempts integer not null default 0 check (attempts >= 0),
  last_error text,
  next_attempt_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (event_id, provider)
);

-- Supporting indexes for dashboards, timelines, filters and retry workers.
create index if not exists visitors_last_seen_idx on public.visitors (last_seen_at desc);
create index if not exists visitor_sessions_started_idx on public.visitor_sessions (started_at desc);
create index if not exists visitor_sessions_visitor_started_idx on public.visitor_sessions (visitor_id, started_at desc);
create index if not exists visitor_sessions_source_idx on public.visitor_sessions (source, started_at desc);
create index if not exists tracking_events_occurred_idx on public.tracking_events (occurred_at desc);
create index if not exists tracking_events_type_time_idx on public.tracking_events (event_type, occurred_at desc);
create index if not exists tracking_events_page_time_idx on public.tracking_events (page_path, occurred_at desc);
create index if not exists tracking_events_session_time_idx on public.tracking_events (session_id, occurred_at asc);
create index if not exists tracking_events_visitor_time_idx on public.tracking_events (visitor_id, occurred_at desc);
create index if not exists tracking_events_source_time_idx on public.tracking_events (source, occurred_at desc);
create index if not exists email_open_events_message_time_idx on public.email_open_events (message_id, requested_at desc);
create index if not exists contact_submissions_created_idx on public.contact_submissions (created_at desc);
create index if not exists contact_submissions_status_idx on public.contact_submissions (status, created_at desc);
create index if not exists admin_activity_logs_created_idx on public.admin_activity_logs (created_at desc);
create index if not exists export_jobs_retry_idx on public.export_jobs (status, next_attempt_at) where status in ('pending', 'failed');

-- Shared updated_at trigger.
create or replace function public.set_updated_at()
returns trigger language plpgsql set search_path = '' as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists visitors_set_updated_at on public.visitors;
create trigger visitors_set_updated_at before update on public.visitors
for each row execute function public.set_updated_at();
drop trigger if exists site_settings_set_updated_at on public.site_settings;
create trigger site_settings_set_updated_at before update on public.site_settings
for each row execute function public.set_updated_at();
drop trigger if exists integration_settings_set_updated_at on public.integration_settings;
create trigger integration_settings_set_updated_at before update on public.integration_settings
for each row execute function public.set_updated_at();
drop trigger if exists admin_profiles_set_updated_at on public.admin_profiles;
create trigger admin_profiles_set_updated_at before update on public.admin_profiles
for each row execute function public.set_updated_at();
drop trigger if exists export_jobs_set_updated_at on public.export_jobs;
create trigger export_jobs_set_updated_at before update on public.export_jobs
for each row execute function public.set_updated_at();

-- Role helper: SECURITY DEFINER avoids recursive RLS when checking admin_profiles.
create or replace function public.is_active_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.admin_profiles p
    where p.user_id = (select auth.uid()) and p.is_active = true
  );
$$;

create or replace function public.is_owner()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.admin_profiles p
    where p.user_id = (select auth.uid()) and p.is_active = true and p.role = 'owner'
  );
$$;

-- Enable RLS on every application table.
alter table public.visitors enable row level security;
alter table public.visitor_sessions enable row level security;
alter table public.tracking_events enable row level security;
alter table public.contact_submissions enable row level security;
alter table public.email_open_events enable row level security;
alter table public.site_settings enable row level security;
alter table public.integration_settings enable row level security;
alter table public.admin_profiles enable row level security;
alter table public.admin_activity_logs enable row level security;
alter table public.export_jobs enable row level security;

-- Admin read policies. All writes are performed by trusted server functions using service role
-- only after validating the user's Auth token and admin role.
create policy "active admins read visitors" on public.visitors for select to authenticated using (public.is_active_admin());
create policy "active admins read sessions" on public.visitor_sessions for select to authenticated using (public.is_active_admin());
create policy "active admins read tracking events" on public.tracking_events for select to authenticated using (public.is_active_admin());
create policy "active admins manage contact submissions" on public.contact_submissions for all to authenticated using (public.is_active_admin()) with check (public.is_active_admin());
create policy "active admins read email events" on public.email_open_events for select to authenticated using (public.is_active_admin());
create policy "active admins read settings" on public.site_settings for select to authenticated using (public.is_active_admin());
create policy "active admins read integrations" on public.integration_settings for select to authenticated using (public.is_active_admin());
create policy "admins read own profile or owner reads all" on public.admin_profiles for select to authenticated using (user_id = (select auth.uid()) or public.is_owner());
create policy "active admins read activity logs" on public.admin_activity_logs for select to authenticated using (public.is_active_admin());
create policy "owners read export jobs" on public.export_jobs for select to authenticated using (public.is_owner());

-- Do not grant anonymous table access. Authenticated reads are additionally constrained by RLS.
revoke all on public.visitors, public.visitor_sessions, public.tracking_events,
  public.contact_submissions, public.email_open_events, public.site_settings,
  public.integration_settings, public.admin_profiles, public.admin_activity_logs,
  public.export_jobs from anon, authenticated;

revoke all on all sequences in schema public from anon, authenticated;

grant select on public.visitors, public.visitor_sessions, public.tracking_events,
  public.contact_submissions, public.email_open_events, public.site_settings,
  public.integration_settings, public.admin_profiles, public.admin_activity_logs,
  public.export_jobs to authenticated;

grant execute on function public.is_active_admin() to authenticated;
grant execute on function public.is_owner() to authenticated;

-- Safe defaults: Sheets remains disabled until explicitly enabled by the owner.
insert into public.integration_settings (provider, enabled, options)
values
  ('google_sheets', false, '{}'::jsonb),
  ('telegram', false, '{}'::jsonb)
on conflict (provider) do nothing;

insert into public.site_settings (key, value, description)
values
  ('tracking', '{"enabled": true, "track_page_views": true, "track_clicks": true, "exclude_admins": true}'::jsonb,
   'Non-secret tracking preferences'),
  ('privacy', '{"visitor_id_retention_days": 180, "event_retention_days": 365, "store_raw_ip": false}'::jsonb,
   'Privacy and retention preferences')
on conflict (key) do nothing;

commit;


-- ==================== 0002_analytics_views.sql ====================
-- Lightweight, bounded aggregate views for the first analytics dashboard.
-- Views contain no direct personal data and exclude admin traffic.
begin;

create or replace view public.analytics_daily_summary
with (security_invoker = true) as
select
  date_trunc('day', e.occurred_at) as day_utc,
  count(*) filter (where e.event_type in ('page_view', 'visit')) as page_views,
  count(distinct e.visitor_id) filter (where e.event_type in ('page_view', 'visit')) as unique_visitors,
  count(distinct e.session_id) filter (where e.event_type in ('page_view', 'visit')) as sessions,
  count(*) filter (where e.event_type = 'whatsapp_click') as whatsapp_clicks,
  count(*) filter (where e.event_type = 'cta_click') as cta_clicks,
  count(*) filter (where e.event_type = 'contact_submit') as contact_submissions
from public.tracking_events e
where e.is_admin = false
group by date_trunc('day', e.occurred_at);

create or replace view public.analytics_top_pages
with (security_invoker = true) as
select
  e.page_path,
  count(*) filter (where e.event_type in ('page_view', 'visit')) as page_views,
  count(distinct e.visitor_id) as unique_visitors
from public.tracking_events e
where e.is_admin = false
  and e.event_type in ('page_view', 'visit')
group by e.page_path;

create or replace view public.analytics_sources
with (security_invoker = true) as
select
  coalesce(nullif(e.source, ''), 'direct / unknown') as source,
  coalesce(nullif(e.campaign, ''), '(not set)') as campaign,
  count(*) as events,
  count(distinct e.visitor_id) as unique_visitors
from public.tracking_events e
where e.is_admin = false
  and e.event_type in ('page_view', 'visit')
group by 1, 2;

-- Views are admin-only. security_invoker means underlying table RLS remains in force.
revoke all on public.analytics_daily_summary, public.analytics_top_pages, public.analytics_sources from anon, authenticated;
grant select on public.analytics_daily_summary, public.analytics_top_pages, public.analytics_sources to authenticated;

commit;


-- ==================== 0003_analytics_rpc.sql ====================
-- Bounded, server-side analytics aggregation. Avoids downloading thousands of raw events.
begin;

create or replace function public.admin_analytics_summary(p_days integer default 30)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_days integer := greatest(1, least(coalesce(p_days, 30), 90));
  v_since timestamptz := now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 90)));
  v_result jsonb;
begin
  if not public.is_active_admin() then
    raise exception 'admin_access_required' using errcode = '42501';
  end if;

  with filtered as (
    select * from public.tracking_events
    where is_admin = false and occurred_at >= v_since
  ), daily as (
    select date_trunc('day', occurred_at) as day_utc,
      count(*) filter (where event_type in ('page_view','visit')) as page_views,
      count(distinct visitor_id) filter (where event_type in ('page_view','visit')) as unique_visitors,
      count(distinct session_id) filter (where event_type in ('page_view','visit')) as sessions,
      count(*) filter (where event_type = 'whatsapp_click') as whatsapp_clicks,
      count(*) filter (where event_type = 'cta_click') as cta_clicks,
      count(*) filter (where event_type = 'contact_submit') as contact_submissions
    from filtered group by 1 order by 1
  ), pages as (
    select page_path, count(*) as page_views, count(distinct visitor_id) as unique_visitors
    from filtered where event_type in ('page_view','visit')
    group by page_path order by page_views desc limit 20
  ), sources as (
    select coalesce(nullif(source,''),'direct / unknown') as source,
      coalesce(nullif(campaign,''),'(not set)') as campaign,
      count(*) as events, count(distinct visitor_id) as unique_visitors
    from filtered where event_type in ('page_view','visit')
    group by 1,2 order by events desc limit 20
  ), event_counts as (
    select event_type, count(*) as total from filtered group by event_type
  ), sessions as (
    select count(*) as total_sessions,
      count(*) filter (where started_at >= v_since) as sessions_in_range,
      count(*) filter (where ended_at is not null and ended_at >= v_since) as ended_sessions
    from public.visitor_sessions where is_admin = false and started_at >= v_since
  ), geography as (
    select coalesce(nullif(country,''),'غير معروف') as country, count(*) as sessions
    from public.visitor_sessions where is_admin = false and started_at >= v_since
    group by 1 order by sessions desc limit 10
  ), devices as (
    select coalesce(nullif(device_type,''),'غير معروف') as device, count(*) as sessions
    from public.visitor_sessions where is_admin = false and started_at >= v_since
    group by 1 order by sessions desc limit 10
  )
  select jsonb_build_object(
    'range_days', v_days,
    'unique_visitors', (select count(distinct visitor_id) from filtered where event_type in ('page_view','visit')),
    'total_page_views', (select count(*) from filtered where event_type in ('page_view','visit')),
    'daily', coalesce((select jsonb_agg(to_jsonb(daily) order by day_utc) from daily), '[]'::jsonb),
    'top_pages', coalesce((select jsonb_agg(to_jsonb(pages)) from pages), '[]'::jsonb),
    'sources', coalesce((select jsonb_agg(to_jsonb(sources)) from sources), '[]'::jsonb),
    'event_counts', coalesce((select jsonb_object_agg(event_type,total) from event_counts), '{}'::jsonb),
    'sessions', (select to_jsonb(sessions) from sessions),
    'countries', coalesce((select jsonb_agg(to_jsonb(geography)) from geography), '[]'::jsonb),
    'devices', coalesce((select jsonb_agg(to_jsonb(devices)) from devices), '[]'::jsonb)
  ) into v_result;
  return v_result;
end;
$$;

revoke all on function public.admin_analytics_summary(integer) from public, anon;
grant execute on function public.admin_analytics_summary(integer) to authenticated;

commit;


-- ==================== 0004_lead_management.sql ====================
-- Lead management: structured CRM fields and notification delivery tracking.
begin;

alter table public.contact_submissions
  add column if not exists company text,
  add column if not exists service text,
  add column if not exists budget text,
  add column if not exists referral_source text,
  add column if not exists admin_note text,
  add column if not exists delivery_status text not null default 'not_configured',
  add column if not exists delivery_error text,
  add column if not exists notification_sent_at timestamptz,
  add column if not exists status_updated_at timestamptz not null default now(),
  add column if not exists updated_at timestamptz not null default now();

alter table public.contact_submissions
  drop constraint if exists contact_submissions_delivery_status_check;
alter table public.contact_submissions
  add constraint contact_submissions_delivery_status_check
  check (delivery_status in ('not_configured', 'sent', 'failed'));

create index if not exists contact_submissions_service_created_idx
  on public.contact_submissions (service, created_at desc);
create index if not exists contact_submissions_email_created_idx
  on public.contact_submissions (lower(email), created_at desc);
create index if not exists contact_submissions_status_updated_idx
  on public.contact_submissions (status_updated_at desc);

create or replace function public.touch_contact_submission()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  if new.status is distinct from old.status then
    new.status_updated_at = now();
  end if;
  return new;
end;
$$;

drop trigger if exists contact_submissions_touch on public.contact_submissions;
create trigger contact_submissions_touch
before update on public.contact_submissions
for each row execute function public.touch_contact_submission();

-- Explicitly keep the table unavailable to anonymous users. Server Functions
-- use the service role only after validating input or an administrator token.
revoke all on public.contact_submissions from anon;
grant select on public.contact_submissions to authenticated;

commit;


-- ==================== 0005_conversion_analytics.sql ====================
-- Lead conversion analytics. All aggregation stays inside PostgreSQL.
begin;

create or replace function public.admin_conversion_summary(p_days integer default 30)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_days integer := greatest(1, least(coalesce(p_days, 30), 90));
  v_since timestamptz := now() - make_interval(days => greatest(1, least(coalesce(p_days, 30), 90)));
  v_result jsonb;
begin
  if not public.is_active_admin() then
    raise exception 'admin_access_required' using errcode = '42501';
  end if;

  with
  views as (
    select * from public.tracking_events
    where is_admin = false
      and event_type in ('page_view', 'visit')
      and occurred_at >= v_since
  ),
  leads as (
    select cs.*,
      coalesce(nullif(btrim(vs.utm_source), ''),
               nullif(btrim(vs.source), ''),
               nullif(btrim(cs.referral_source), ''),
               'direct / unknown') as attributed_source
    from public.contact_submissions cs
    left join public.visitor_sessions vs on vs.id = cs.session_id
    where cs.created_at >= v_since
  ),
  visitor_sources as (
    select coalesce(nullif(btrim(vs.utm_source), ''), nullif(btrim(vs.source), ''), 'direct / unknown') as source,
           count(distinct vs.visitor_id) as visitors
    from public.visitor_sessions vs
    where vs.is_admin = false and vs.started_at >= v_since
    group by 1
  ),
  lead_sources as (
    select attributed_source as source,
           count(*) as leads,
           count(distinct visitor_id) as converted_visitors
    from leads
    where status <> 'spam'
    group by 1
  ),
  source_rows as (
    select coalesce(vs.source, ls.source) as source,
           coalesce(vs.visitors, 0) as visitors,
           coalesce(ls.leads, 0) as leads,
           coalesce(ls.converted_visitors, 0) as converted_visitors,
           case when coalesce(vs.visitors, 0) > 0
             then round((coalesce(ls.converted_visitors, 0)::numeric / vs.visitors) * 100, 2)
             else 0 end as conversion_rate
    from visitor_sources vs
    full outer join lead_sources ls on ls.source = vs.source
  ),
  daily_dates as (
    select generate_series(date_trunc('day', v_since), date_trunc('day', now()), interval '1 day') as day_utc
  ),
  daily_rows as (
    select d.day_utc,
      (select count(*) from views v where v.occurred_at >= d.day_utc and v.occurred_at < d.day_utc + interval '1 day') as page_views,
      (select count(distinct v.visitor_id) from views v where v.occurred_at >= d.day_utc and v.occurred_at < d.day_utc + interval '1 day') as visitors,
      (select count(*) from leads l where l.created_at >= d.day_utc and l.created_at < d.day_utc + interval '1 day' and l.status <> 'spam') as leads
    from daily_dates d
  ),
  service_rows as (
    select coalesce(nullif(btrim(service), ''), 'غير محدد') as service, count(*) as leads
    from leads where status <> 'spam'
    group by 1 order by leads desc limit 12
  ),
  status_rows as (
    select status, count(*) as total from leads group by status
  ),
  page_rows as (
    select coalesce(nullif(source_page, ''), '/') as page_path,
      count(*) as leads,
      count(distinct visitor_id) as converted_visitors
    from leads where status <> 'spam'
    group by 1 order by leads desc limit 12
  ),
  totals as (
    select
      (select count(distinct visitor_id) from views) as unique_visitors,
      (select count(*) from views) as page_views,
      (select count(*) from public.visitor_sessions where is_admin = false and started_at >= v_since) as sessions,
      (select count(*) from leads where status <> 'spam') as total_leads,
      (select count(distinct visitor_id) from leads where status <> 'spam' and visitor_id is not null) as converted_visitors,
      (select count(*) from leads where status in ('new','in_progress')) as open_leads,
      (select count(*) from leads where status = 'replied') as replied_leads,
      (select count(*) from leads where status = 'closed') as closed_leads,
      (select count(*) from leads where status = 'spam') as spam_leads,
      (select count(*) from public.tracking_events where is_admin = false and event_type = 'whatsapp_click' and occurred_at >= v_since) as whatsapp_clicks
  )
  select jsonb_build_object(
    'range_days', v_days,
    'totals', jsonb_build_object(
      'unique_visitors', totals.unique_visitors,
      'page_views', totals.page_views,
      'sessions', totals.sessions,
      'total_leads', totals.total_leads,
      'converted_visitors', totals.converted_visitors,
      'conversion_rate', case when totals.unique_visitors > 0 then round((totals.converted_visitors::numeric / totals.unique_visitors) * 100, 2) else 0 end,
      'lead_rate', case when totals.unique_visitors > 0 then round((totals.total_leads::numeric / totals.unique_visitors) * 100, 2) else 0 end,
      'open_leads', totals.open_leads,
      'replied_leads', totals.replied_leads,
      'closed_leads', totals.closed_leads,
      'spam_leads', totals.spam_leads,
      'whatsapp_clicks', totals.whatsapp_clicks
    ),
    'daily', coalesce((select jsonb_agg(to_jsonb(daily_rows) order by day_utc) from daily_rows), '[]'::jsonb),
    'sources', coalesce((select jsonb_agg(to_jsonb(source_rows) order by leads desc, visitors desc) from source_rows), '[]'::jsonb),
    'services', coalesce((select jsonb_agg(to_jsonb(service_rows) order by leads desc) from service_rows), '[]'::jsonb),
    'statuses', coalesce((select jsonb_object_agg(status, total) from status_rows), '{}'::jsonb),
    'top_pages', coalesce((select jsonb_agg(to_jsonb(page_rows) order by leads desc) from page_rows), '[]'::jsonb)
  ) into v_result
  from totals;

  return v_result;
end;
$$;

revoke all on function public.admin_conversion_summary(integer) from public, anon;
grant execute on function public.admin_conversion_summary(integer) to authenticated;

commit;


-- ==================== 0006_security_hardening.sql ====================
-- Final privilege hardening for helper/trigger functions.
-- Trigger functions remain executable by PostgreSQL triggers; they are not callable as app RPCs.
begin;

revoke all on function public.set_updated_at() from public, anon, authenticated;
revoke all on function public.touch_contact_submission() from public, anon, authenticated;
revoke all on function public.is_active_admin() from public, anon;
revoke all on function public.is_owner() from public, anon;

-- Explicitly lock down the privileged aggregation RPCs to authenticated callers.
-- Their SECURITY DEFINER bodies independently verify active-admin membership.
revoke all on function public.admin_analytics_summary(integer) from public, anon;
revoke all on function public.admin_conversion_summary(integer) from public, anon;
grant execute on function public.admin_analytics_summary(integer) to authenticated;
grant execute on function public.admin_conversion_summary(integer) to authenticated;
grant execute on function public.is_active_admin() to authenticated;
grant execute on function public.is_owner() to authenticated;

-- No direct authenticated writes to privileged tables; Pages Functions use the privileged server credential
-- only after validating the caller's Supabase access token and admin profile.
revoke insert, update, delete, truncate, references, trigger
  on public.visitors, public.visitor_sessions, public.tracking_events,
     public.contact_submissions, public.email_open_events, public.site_settings,
     public.integration_settings, public.admin_profiles, public.admin_activity_logs,
     public.export_jobs
  from anon, authenticated;

commit;


-- ==================== 0007_admin_bootstrap_hardening.sql ====================
begin;

-- Admin profile writes remain server-only. This migration documents and enforces
-- that authenticated browser roles cannot mutate admin_profiles directly.
revoke insert, update, delete on public.admin_profiles from anon, authenticated;
revoke insert, update, delete on public.admin_activity_logs from anon, authenticated;

-- No public bootstrap RPC is intentionally provided. The first owner is provisioned
-- once through the Supabase Dashboard + SQL Editor (see docs/ADMIN_ACCOUNT_SETUP.md).

commit;


-- ==================== POST-MIGRATION STRUCTURAL VERIFICATION ====================
-- Run after all seven migrations in the Supabase SQL Editor.
-- Structural verification only; identity-based RLS acceptance tests remain separate.
do $$
declare
  required_tables text[] := array[
    'visitors','visitor_sessions','tracking_events','contact_submissions',
    'email_open_events','site_settings','integration_settings','admin_profiles',
    'admin_activity_logs','export_jobs'
  ];
  required_views text[] := array[
    'analytics_daily_summary','analytics_top_pages','analytics_sources'
  ];
  required_functions text[] := array[
    'is_active_admin','is_owner','admin_analytics_summary','admin_conversion_summary'
  ];
  item text;
  missing_count integer;
begin
  foreach item in array required_tables loop
    if to_regclass(format('public.%I', item)) is null then
      raise exception 'Missing required table: public.%', item;
    end if;
    if not exists (
      select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace
      where n.nspname='public' and c.relname=item and c.relrowsecurity
    ) then
      raise exception 'RLS is not enabled on public.%', item;
    end if;
  end loop;

  foreach item in array required_views loop
    if to_regclass(format('public.%I', item)) is null then
      raise exception 'Missing required view: public.%', item;
    end if;
  end loop;

  foreach item in array required_functions loop
    if not exists (
      select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
      where n.nspname='public' and p.proname=item
    ) then
      raise exception 'Missing required function: public.%', item;
    end if;
  end loop;

  -- Privileged tables must not grant browser-role writes.
  if has_table_privilege('anon', 'public.admin_profiles', 'INSERT')
     or has_table_privilege('authenticated', 'public.admin_profiles', 'INSERT')
     or has_table_privilege('anon', 'public.admin_profiles', 'UPDATE')
     or has_table_privilege('authenticated', 'public.admin_profiles', 'UPDATE') then
    raise exception 'Unexpected browser-role write privilege on admin_profiles';
  end if;

  -- Browser roles must not execute the trigger-maintenance function directly.
  if has_function_privilege('anon', 'public.set_updated_at()', 'EXECUTE')
     or has_function_privilege('authenticated', 'public.set_updated_at()', 'EXECUTE') then
    raise exception 'Unexpected browser-role EXECUTE privilege on set_updated_at';
  end if;

  select count(*) into missing_count
  from (values
    ('active admins read visitors'),
    ('active admins read sessions'),
    ('active admins read tracking events'),
    ('admins read own profile or owner reads all'),
    ('owners read export jobs')
  ) expected(policy_name)
  where not exists (
    select 1 from pg_policies p
    where p.schemaname='public' and p.policyname=expected.policy_name
  );
  if missing_count > 0 then
    raise exception 'Missing % expected RLS policies', missing_count;
  end if;

  raise notice 'Supabase structural verification passed: % tables, % views, % functions, RLS and key grants checked.',
    cardinality(required_tables), cardinality(required_views), cardinality(required_functions);
end;
$$;
